import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';import 'package:supabase_flutter/supabase_flutter.dart';import '../config/subscription_config.dart';import '../theme/app_theme.dart';
class ShopSubscriptionScreen extends StatefulWidget{const ShopSubscriptionScreen({super.key});@override State<ShopSubscriptionScreen> createState()=>_ShopSubscriptionScreenState();}
class _ShopSubscriptionScreenState extends State<ShopSubscriptionScreen>{Map<String,dynamic>? _current;bool _loading=true;Future<void> _load()async{final uid=Supabase.instance.client.auth.currentUser!.id;final row=await Supabase.instance.client.from('shop_subscriptions').select('*').eq('shop_id',uid).order('requested_at',ascending:false).limit(1).maybeSingle();if(mounted)setState(()=>_current=row);setState(()=>_loading=false);}
@override void initState(){super.initState();_load();}
Future<void> _proof()async{final uid=Supabase.instance.client.auth.currentUser!.id;final img=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:80,maxWidth:1600);if(img==null)return;final path=uid+'/proof_'+DateTime.now().millisecondsSinceEpoch.toString()+'.jpg';await Supabase.instance.client.storage.from('subscription-proofs').uploadBinary(path,await img.readAsBytes(),fileOptions:const FileOptions(contentType:'image/jpeg'));await Supabase.instance.client.from('shop_subscriptions').insert({'shop_id':uid,'payment_proof_path':path,'status':'pending'});_load();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('اشتراك المعرض')),body:_loading?const Center(child:CircularProgressIndicator(color:AppColors.gold)):ListView(padding:const EdgeInsets.all(16),children:[const Card(child:Padding(padding:EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('المزايا',style:TextStyle(fontWeight:FontWeight.bold)),Text('• ظهور أعلى عند ترتيب الأحدث\n• وسم معرض مميز')])),const SizedBox(height:12),Text('السعر: '+(SubscriptionConfig.priceSdg==0?'السعر تحدده الإدارة':SubscriptionConfig.priceSdg.toString()+' ج.س')),Text('المدة: '+SubscriptionConfig.durationDays.toString()+' يوماً'),const SizedBox(height:8),Text(SubscriptionConfig.paymentInstructions),const SizedBox(height:16),Text('الحالة: '+(_current?['status']?.toString()??'لا يوجد')),const SizedBox(height:12),ElevatedButton(onPressed:_proof,child:const Text('إرسال إثبات الدفع'))]) );}
}